#!/usr/bin/env node
/**
 * Tests for the deliver flow wording: the stale test title, the SKILL.md size table, the challenger at every
 * M and L, the plan-only stop, and a clean kit validation.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (rel) => readFileSync(join(ROOT, rel), 'utf8');

/** Every file under `dir` (repo-relative), recursive. */
function filesUnder(dir) {
  return readdirSync(join(ROOT, dir)).flatMap((n) => {
    const rel = `${dir}/${n}`;
    return statSync(join(ROOT, rel)).isDirectory() ? filesUnder(rel) : [rel];
  });
}

test('given tools/dev-loop-blocks.test.mjs, when grepped for the stale size title, then 0 hits', () => {
  // Given
  const stale = ['size M and', 'two blocks'].join(' ');

  // When
  const hits = read('tools/dev-loop-blocks.test.mjs').split('\n').filter((l) => l.includes(stale));

  // Then
  assert.equal(hits.length, 0);
});

test('given SKILL.md section 2 table, when the M review cell is read, then it says reader A is skipped with one block and reader B reads the whole diff', () => {
  // Given
  const row = read('skills/deliver/SKILL.md').split('\n').find((l) => l.startsWith('| review |'));

  // When
  const cell = row.split('|')[3];

  // Then
  assert.match(cell, /reader A is skipped with one block/);
  assert.match(cell, /reader B reads the whole diff/);
});

test('given skills/deliver, when grepped for the planner replacing the challenger, then 0 hits', () => {
  // Given
  const phrase = ['replaces', 'the challenger'].join(' ');

  // When
  const hits = filesUnder('skills/deliver').filter((f) => read(f).toLowerCase().includes(phrase));

  // Then
  assert.deepEqual(hits, []);
});

test('given analysis.md, when read, then the order is interpret+doubts, plan, challenger, owner ok, loop', () => {
  // Given
  const text = read('skills/deliver/references/analysis.md');

  // When
  const line = text.split('\n').find((l) => /interpret/i.test(l) && /doubts/i.test(l) && /challenger/i.test(l) && /owner ok/i.test(l));

  // Then
  assert.ok(line, 'no line states the order');
  const at = ['interpret', 'doubts', 'plan', 'challenger', 'owner ok', 'loop'].map((w) => line.toLowerCase().indexOf(w, 0));
  assert.ok(at.every((i) => i >= 0), line);
  assert.deepEqual(at, [...at].sort((a, b) => a - b), line);
  assert.match(text, /Opus `?Plan`? at L or (a )?sensitive M/i);
  assert.match(text, /this session at plain M/i);
  assert.match(text, /Sonnet high, Opus with (a )?security or data/i);
});

test('given analysis.md, when read for a plan-only request, then it stops after the owner ok', () => {
  // Given
  const text = read('skills/deliver/references/analysis.md');

  // When
  const line = text.split('\n').find((l) => /plan-only/i.test(l));

  // Then
  assert.ok(line, 'no line covers a plan-only request');
  assert.match(line, /stops? after the owner ok/i);
});

test('given the kit, when node tools/validate.mjs runs, then it is clean', () => {
  // Given
  const script = join(ROOT, 'tools', 'validate.mjs');

  // When
  const res = spawnSync(process.execPath, [script], { encoding: 'utf8', cwd: ROOT });

  // Then
  assert.equal(res.status, 0, res.stdout + res.stderr);
  assert.ok(!/ERROR/.test(res.stdout), res.stdout);
});
